from rdkit import Chem
rxn='[C][C][C@@H1][Branch1][C][N][C][=C][C][=C][C][=C][Ring1][=Branch1].[O][=C][Branch1][C][O][C][C][=C][N][C][=Ring1][Branch1][C][C][C][C][Ring1][=Branch1]>>[C][C][C@@H1][Branch2][Ring1][Ring1][N][C][=Branch1][C][=O][C][C][=C][N][C][=Ring1][Branch1][C][C][C][C][Ring1][=Branch1][C][=C][C][=C][C][=C][Ring1][=Branch1]'
for part in rxn.split('>>'):
    print('PART',part)
    for s in part.split('.'):
        m=Chem.MolFromSmiles(s)
        print('parsed',m is not None)
        if m:
            print(Chem.MolToSmiles(m))
            print([(a.GetIdx(),a.GetSymbol(),a.GetIsAromatic(),a.GetFormalCharge()) for a in m.GetAtoms()])
            print([(b.GetBeginAtomIdx(),b.GetEndAtomIdx(),str(b.GetBondType())) for b in m.GetBonds()])
        else:
            print(Chem.MolFromSmiles(s,sanitize=False))

